"use client";

import { useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import { toast } from "sonner";
import {
  ArrowRight,
  Loader2,
  ShieldCheck,
  Lock,
  ChevronRight,
  AlertTriangle,
  FlaskConical,
} from "lucide-react";

import { AuthLayout } from "@/components/auth/AuthLayout";
import { Button } from "@/components/ui/button";
import { isValidNIN } from "@/lib/auth/actions";
import { useAuthStore } from "@/store/useAuthStore";

const ninSchema = z.object({
  nin: z
    .string()
    .min(1, "National Identity Number is required")
    .transform((val) => val.replace(/\D/g, ""))
    .refine(
      (val) => isValidNIN(val),
      "National Identity Number must be exactly 11 numeric digits"
    ),
});

type NinFormData = z.infer<typeof ninSchema>;

export default function VerifyNinPage() {
  const router = useRouter();
  const { fetchProfile } = useAuthStore();
  const [isLoading, setIsLoading] = useState(false);

  const {
    register,
    handleSubmit,
    watch,
    formState: { errors },
  } = useForm<NinFormData>({
    resolver: zodResolver(ninSchema),
    defaultValues: {
      nin: "",
    },
  });

  const ninRaw = watch("nin") || "";
  const cleanedNin = ninRaw.replace(/\D/g, "");

  const onSubmit = async (data: NinFormData) => {
    setIsLoading(true);
    try {
      const response = await fetch("/api/nin/verify", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ nin: data.nin }),
      });

      const result = await response.json();

      if (!response.ok || !result.success) {
        throw new Error(result.error || "Failed to verify NIN.");
      }

      // Refresh store profile so is_verified updates across all components
      await fetchProfile();

      toast.success(result.message || "National Identity verified successfully!");
      router.push("/home");
      router.refresh();
    } catch (err: any) {
      toast.error(
        err.message || "Failed to verify NIN. Please check the digits and try again."
      );
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <AuthLayout
      title="Harmonise your NIN"
      subtitle="Verify your National Identity Number to unlock Rookie (Level 1)."
      rightHeadline={
        <>
          Identity privacy
          <br />
          by <span className="font-serif italic font-normal text-emerald-400">design.</span>
        </>
      }
      rightSubtext="Your NIN is sent over an encrypted connection, hashed with a secret salt on our server, and the raw number is never stored or logged. Only the hash is kept."
      rightFooterLeft="HASHED, NEVER STORED"
      rightFooterRight="DEMO MODE"
    >
      <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
        {/* Prominent Demo Verification Notice */}
        <div className="rounded-xl border border-amber-500/30 bg-amber-500/10 p-4 space-y-1.5 text-amber-600 dark:text-amber-400">
          <div className="flex items-center gap-2 text-xs font-semibold uppercase tracking-wider">
            <FlaskConical className="h-4 w-4 shrink-0" />
            <span>Demo Verification Sandbox</span>
          </div>
          <p className="text-xs leading-relaxed text-amber-700 dark:text-amber-300">
            This is a mock verification environment for testing. You can enter any 11 digits (e.g.{" "}
            <code className="font-mono font-bold bg-amber-500/20 px-1 py-0.5 rounded">
              12345678901
            </code>
            ) to simulate verification and unlock Rookie (Level 1) in demo mode. No real NIMC check is performed.
          </p>
        </div>

        {/* NIN Input Field */}
        <div className="space-y-2">
          <div className="flex items-center justify-between">
            <label className="text-xs font-mono uppercase tracking-wider text-muted-foreground block">
              11-Digit National Identity Number
            </label>
            <span className="font-mono text-[11px] text-muted-foreground">
              {cleanedNin.length}/11 Digits
            </span>
          </div>

          <div
            className={`flex h-14 items-center gap-3 rounded-xl border bg-secondary/30 px-4 transition-all focus-within:border-primary focus-within:ring-1 focus-within:ring-primary ${
              errors.nin ? "border-destructive bg-destructive/5" : "border-hairline"
            }`}
          >
            <ShieldCheck className="h-4 w-4 text-primary shrink-0" />
            <input
              type="text"
              inputMode="numeric"
              maxLength={11}
              placeholder="e.g. 12345678901"
              disabled={isLoading}
              className="h-full w-full bg-transparent font-mono text-base tracking-wider text-foreground outline-none placeholder:text-muted-foreground/50 placeholder:font-sans disabled:opacity-50"
              {...register("nin")}
            />
          </div>

          {errors.nin && (
            <p className="text-xs font-medium text-destructive mt-1">
              {errors.nin.message}
            </p>
          )}
        </div>

        {/* Plain Language Privacy Note */}
        <div className="rounded-xl border border-hairline bg-secondary/30 p-4 space-y-2">
          <div className="flex items-center gap-2 text-xs font-semibold text-foreground">
            <Lock className="h-3.5 w-3.5 text-primary shrink-0" />
            <span>How your National Identity is protected</span>
          </div>
          <p className="type-small text-[11px] text-muted-foreground leading-relaxed">
            Your NIN is sent securely to our server, hashed with salted SHA-256, and the raw number is never stored or logged. This is a demo, so no real NIMC check is made.
          </p>
        </div>

        {/* Submit Action */}
        <Button
          type="submit"
          disabled={isLoading || cleanedNin.length !== 11}
          className="h-12 w-full rounded-xl bg-primary text-primary-foreground font-semibold hover:bg-primary/90 text-sm sm:text-base gap-2 shadow-lg shadow-primary/10 transition-all min-h-[44px]"
        >
          {isLoading ? (
            <>
              <Loader2 className="h-4 w-4 animate-spin" />
              <span>Verifying National Identity...</span>
            </>
          ) : (
            <>
              <span>Verify National Identity</span>
              <ArrowRight className="h-4 w-4" />
            </>
          )}
        </Button>

        {/* Skip for now Link */}
        <div className="text-center pt-1">
          <Link
            href="/home"
            className="inline-flex items-center gap-1 text-xs text-muted-foreground hover:text-foreground transition-colors font-mono uppercase tracking-wider"
          >
            <span>Skip for now</span>
            <ChevronRight className="h-3.5 w-3.5" />
          </Link>
        </div>
      </form>
    </AuthLayout>
  );
}

import type { Metadata } from "next";
import { Suspense } from "react";
import { requireAdmin, maskPhone } from "@/lib/auth/admin-guard";
import { createAdminClient } from "@/lib/supabase/admin";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { ScrollText, ShieldAlert, Clock, User, Terminal } from "lucide-react";

export const metadata: Metadata = {
  title: "Admin Console — Audit Log",
  description: "Immutable administrative action ledger and compliance records",
};

interface AuditLogRow {
  id: string;
  admin_id: string;
  action: string;
  target_type: string;
  target_id: string | null;
  metadata: Record<string, unknown> | null;
  created_at: string;
  admin_user?: {
    full_name: string | null;
    phone_number: string | null;
  } | null;
}

function getActionBadge(action: string) {
  if (action === "user.delete") {
    return {
      label: "USER DELETED",
      cls: "border-destructive/30 bg-destructive/10 text-destructive",
    };
  }
  if (action === "user.role_change") {
    return {
      label: "ROLE CHANGED",
      cls: "border-amber-500/30 bg-amber-500/10 text-amber-500",
    };
  }
  if (action === "report.delete") {
    return {
      label: "REPORT DELETED",
      cls: "border-rose-500/30 bg-rose-500/10 text-rose-400",
    };
  }
  if (action === "report.bulk_delete") {
    return {
      label: "BULK REPORT DELETE",
      cls: "border-destructive/30 bg-destructive/10 text-destructive",
    };
  }
  if (action === "users.export_csv") {
    return {
      label: "CSV EXPORT",
      cls: "border-blue-500/30 bg-blue-500/10 text-blue-400",
    };
  }
  return {
    label: action.toUpperCase(),
    cls: "border-border text-muted-foreground",
  };
}

async function AuditLogContent() {
  await requireAdmin();
  const admin = createAdminClient();

  // Fetch audit logs with admin user details
  const { data: logs, error } = await admin
    .from("admin_audit_log")
    .select(`
      id,
      admin_id,
      action,
      target_type,
      target_id,
      metadata,
      created_at,
      admin_user:admin_id (
        full_name,
        phone_number
      )
    `)
    .order("created_at", { ascending: false })
    .limit(200);

  if (error) {
    // If the table doesn't exist yet in Supabase, show a friendly guide with the exact SQL
    return (
      <Card className="p-6 border-amber-500/30 bg-amber-500/5 space-y-4">
        <div className="flex items-center gap-2 text-amber-500">
          <Terminal className="h-5 w-5" />
          <h3 className="text-sm font-bold">Audit Log Table Needs Setup</h3>
        </div>
        <p className="text-xs text-muted-foreground">
          The <code className="font-mono text-foreground">admin_audit_log</code> table has not been created yet in your Supabase database. Run the migration script in Supabase SQL Editor:
        </p>
        <div className="rounded-lg border border-border bg-card p-4 font-mono text-[11px] text-foreground overflow-x-auto">
          <pre>{`CREATE TABLE IF NOT EXISTS public.admin_audit_log (
  id           UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  admin_id     UUID NOT NULL REFERENCES public.users (id) ON DELETE CASCADE,
  action       TEXT NOT NULL,
  target_type  TEXT NOT NULL,
  target_id    TEXT,
  metadata     JSONB DEFAULT '{}'::jsonb,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE public.admin_audit_log ENABLE ROW LEVEL SECURITY;

CREATE POLICY "admin_audit_log: admin select"
  ON public.admin_audit_log FOR SELECT
  USING (EXISTS (SELECT 1 FROM public.users WHERE public.users.id = auth.uid() AND public.users.role = 'admin'));

CREATE POLICY "admin_audit_log: insert"
  ON public.admin_audit_log FOR INSERT
  WITH CHECK (auth.uid() = admin_id OR auth.role() = 'service_role');`}</pre>
        </div>
      </Card>
    );
  }

  const logList = (logs as unknown as AuditLogRow[]) ?? [];

  if (logList.length === 0) {
    return (
      <Card className="p-12 border-border bg-card text-center space-y-2">
        <ScrollText className="h-8 w-8 text-muted-foreground mx-auto opacity-40" />
        <p className="text-sm font-semibold text-foreground">No Audit Records Yet</p>
        <p className="text-xs text-muted-foreground font-mono">
          Administrative actions (deletions, role changes, CSV exports) will be logged here automatically.
        </p>
      </Card>
    );
  }

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between text-xs text-muted-foreground font-mono px-1">
        <span>{logList.length} recorded events (newest first)</span>
        <span className="text-emerald-500 flex items-center gap-1">
          <span className="h-1.5 w-1.5 rounded-full bg-emerald-500 animate-pulse" />
          Immutable Append-Only Ledger
        </span>
      </div>

      <Card className="border-border bg-card shadow-xs overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-xs">
            <thead>
              <tr className="border-b border-border bg-secondary/20">
                <th className="text-left px-4 py-3 font-mono uppercase tracking-wider text-muted-foreground font-semibold text-[10px] whitespace-nowrap">
                  Timestamp
                </th>
                <th className="text-left px-4 py-3 font-mono uppercase tracking-wider text-muted-foreground font-semibold text-[10px] whitespace-nowrap">
                  Administrator
                </th>
                <th className="text-left px-4 py-3 font-mono uppercase tracking-wider text-muted-foreground font-semibold text-[10px] whitespace-nowrap">
                  Action
                </th>
                <th className="text-left px-4 py-3 font-mono uppercase tracking-wider text-muted-foreground font-semibold text-[10px] whitespace-nowrap">
                  Target
                </th>
                <th className="text-left px-4 py-3 font-mono uppercase tracking-wider text-muted-foreground font-semibold text-[10px] whitespace-nowrap">
                  Details / Metadata
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border/60">
              {logList.map((entry) => {
                const badge = getActionBadge(entry.action);
                const adminName = entry.admin_user?.full_name || "Administrator";

                return (
                  <tr key={entry.id} className="hover:bg-secondary/30 transition-colors">
                    {/* Timestamp */}
                    <td className="px-4 py-3 font-mono text-muted-foreground whitespace-nowrap text-[11px]">
                      {new Date(entry.created_at).toLocaleString("en-GB", {
                        day: "numeric",
                        month: "short",
                        year: "numeric",
                        hour: "2-digit",
                        minute: "2-digit",
                        second: "2-digit",
                      })}
                    </td>

                    {/* Admin */}
                    <td className="px-4 py-3 font-medium text-foreground whitespace-nowrap">
                      <div className="flex items-center gap-1.5">
                        <User className="h-3.5 w-3.5 text-muted-foreground" />
                        <span>{adminName}</span>
                      </div>
                    </td>

                    {/* Action */}
                    <td className="px-4 py-3 whitespace-nowrap">
                      <Badge
                        variant="outline"
                        className={`text-[9px] font-mono font-bold py-0.5 px-2 ${badge.cls}`}
                      >
                        {badge.label}
                      </Badge>
                    </td>

                    {/* Target */}
                    <td className="px-4 py-3 font-mono text-muted-foreground whitespace-nowrap text-[11px]">
                      <span className="uppercase text-foreground font-semibold">
                        {entry.target_type}
                      </span>
                      {entry.target_id && (
                        <span className="text-[10px] text-muted-foreground ml-1.5 truncate max-w-[100px] inline-block align-bottom">
                          #{entry.target_id.slice(0, 8)}...
                        </span>
                      )}
                    </td>

                    {/* Metadata */}
                    <td className="px-4 py-3 font-mono text-[11px] text-muted-foreground max-w-sm truncate">
                      {entry.metadata && Object.keys(entry.metadata).length > 0 ? (
                        <span className="bg-secondary/60 rounded px-1.5 py-0.5 border border-border/60 text-foreground">
                          {JSON.stringify(entry.metadata)}
                        </span>
                      ) : (
                        "—"
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </Card>
    </div>
  );
}

export default function AdminAuditLogPage() {
  return (
    <div className="space-y-4 max-w-[1400px] mx-auto">
      <div>
        <h2 className="text-base font-bold tracking-tight text-foreground">
          Administrative Audit Log
        </h2>
        <p className="text-xs text-muted-foreground mt-0.5">
          Immutable audit trail tracking all administrative actions, data exports, and deletions.
        </p>
      </div>

      <Suspense
        fallback={
          <Card className="p-6 border-border bg-card space-y-3">
            {[...Array(6)].map((_, i) => (
              <Skeleton key={i} className="h-10 w-full" />
            ))}
          </Card>
        }
      >
        <AuditLogContent />
      </Suspense>
    </div>
  );
}

