"use client";

import { useState, useMemo, useTransition } from "react";
import { useRouter } from "next/navigation";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Trash2,
  Filter,
  MapPin,
  Clock,
  Loader2,
  Calendar,
  AlertTriangle,
} from "lucide-react";
import { toast } from "sonner";
import { DeleteReportButton } from "./DeleteReportButton";
import { bulkDeleteReports } from "./actions";

export interface ReportItem {
  id: string;
  center_name: string;
  state: string;
  wait_minutes: number;
  reported_at: string;
  user_id: string;
  reporter_name: string;
  masked_phone: string;
}

interface ReportsTableClientProps {
  reports: ReportItem[];
  availableCentres: string[];
  availableStates: string[];
}

function waitBadge(mins: number) {
  if (mins < 60)
    return { label: "Quiet", cls: "border-emerald-500/30 bg-emerald-500/10 text-emerald-500" };
  if (mins <= 180)
    return { label: "Moderate", cls: "border-amber-500/30 bg-amber-500/10 text-amber-500" };
  return { label: "Busy", cls: "border-destructive/30 bg-destructive/10 text-destructive" };
}

function formatMinutes(m: number) {
  if (m < 60) return `${m}m`;
  const h = Math.floor(m / 60);
  const rem = m % 60;
  return rem > 0 ? `${h}h ${rem}m` : `${h}h`;
}

export function ReportsTableClient({
  reports,
  availableCentres,
  availableStates,
}: ReportsTableClientProps) {
  const router = useRouter();
  const [filterState, setFilterState] = useState<string>("all");
  const [filterCentre, setFilterCentre] = useState<string>("all");
  const [filterDate, setFilterDate] = useState<string>("all");
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [bulkDialogOpen, setBulkDialogOpen] = useState(false);
  const [isBulkPending, startBulkTransition] = useTransition();

  // Filter logic
  const filteredReports = useMemo(() => {
    const now = Date.now();
    return reports.filter((r) => {
      if (filterState !== "all" && r.state !== filterState) return false;
      if (filterCentre !== "all" && r.center_name !== filterCentre) return false;

      if (filterDate !== "all") {
        const reportTime = new Date(r.reported_at).getTime();
        if (filterDate === "24h" && now - reportTime > 24 * 60 * 60 * 1000) return false;
        if (filterDate === "7d" && now - reportTime > 7 * 24 * 60 * 60 * 1000) return false;
        if (filterDate === "30d" && now - reportTime > 30 * 24 * 60 * 60 * 1000) return false;
      }

      return true;
    });
  }, [reports, filterState, filterCentre, filterDate]);

  // Bulk selection handlers
  const handleSelectAll = (checked: boolean) => {
    if (checked) {
      setSelectedIds(filteredReports.map((r) => r.id));
    } else {
      setSelectedIds([]);
    }
  };

  const handleSelectRow = (id: string, checked: boolean) => {
    if (checked) {
      setSelectedIds((prev) => [...prev, id]);
    } else {
      setSelectedIds((prev) => prev.filter((item) => item !== id));
    }
  };

  const isAllSelected =
    filteredReports.length > 0 && selectedIds.length === filteredReports.length;

  const handleBulkDelete = () => {
    startBulkTransition(async () => {
      const res = await bulkDeleteReports(selectedIds);
      if (!res.success) {
        toast.error(res.error || "Failed to bulk delete reports.");
      } else {
        toast.success(`Successfully deleted ${res.count || selectedIds.length} reports.`);
        setSelectedIds([]);
        setBulkDialogOpen(false);
        router.refresh();
      }
    });
  };

  return (
    <div className="space-y-4">
      {/* Filters & Bulk Action Bar */}
      <Card className="p-3.5 border-border bg-card shadow-xs">
        <div className="flex flex-col md:flex-row items-stretch md:items-center justify-between gap-3">
          {/* Filters */}
          <div className="flex flex-wrap items-center gap-2 flex-1">
            <div className="flex items-center gap-1.5 text-xs font-semibold text-muted-foreground font-mono uppercase pr-1">
              <Filter className="h-3.5 w-3.5 text-primary" />
              <span>Filter:</span>
            </div>

            {/* Filter: State */}
            <select
              value={filterState}
              onChange={(e) => setFilterState(e.target.value)}
              className="h-8 px-2.5 rounded-md border border-border bg-secondary/40 text-xs text-foreground outline-none focus:border-primary transition-colors"
            >
              <option value="all">All States</option>
              {availableStates.map((st) => (
                <option key={st} value={st}>
                  {st}
                </option>
              ))}
            </select>

            {/* Filter: Centre */}
            <select
              value={filterCentre}
              onChange={(e) => setFilterCentre(e.target.value)}
              className="h-8 px-2.5 rounded-md border border-border bg-secondary/40 text-xs text-foreground outline-none focus:border-primary transition-colors max-w-[200px]"
            >
              <option value="all">All Centres</option>
              {availableCentres.map((c) => (
                <option key={c} value={c}>
                  {c}
                </option>
              ))}
            </select>

            {/* Filter: Date */}
            <select
              value={filterDate}
              onChange={(e) => setFilterDate(e.target.value)}
              className="h-8 px-2.5 rounded-md border border-border bg-secondary/40 text-xs text-foreground outline-none focus:border-primary transition-colors"
            >
              <option value="all">All Time</option>
              <option value="24h">Last 24 Hours</option>
              <option value="7d">Last 7 Days</option>
              <option value="30d">Last 30 Days</option>
            </select>
          </div>

          {/* Bulk Action Button (active when items selected) */}
          {selectedIds.length > 0 && (
            <div className="flex items-center gap-2 animate-in fade-in duration-200">
              <span className="text-xs font-mono text-muted-foreground">
                {selectedIds.length} selected
              </span>
              <Button
                variant="destructive"
                size="sm"
                onClick={() => setBulkDialogOpen(true)}
                className="h-8 text-xs gap-1.5"
              >
                <Trash2 className="h-3 w-3" />
                <span>Delete Selected ({selectedIds.length})</span>
              </Button>
            </div>
          )}
        </div>
      </Card>

      {/* Count Info */}
      <div className="text-xs text-muted-foreground font-mono px-1">
        Showing {filteredReports.length} of {reports.length} reports
        {(filterState !== "all" || filterCentre !== "all" || filterDate !== "all") &&
          " (filtered)"}
      </div>

      {/* Main Table */}
      <Card className="border-border bg-card shadow-xs overflow-hidden">
        {filteredReports.length === 0 ? (
          <div className="p-12 text-center space-y-2">
            <MapPin className="h-8 w-8 text-muted-foreground mx-auto opacity-40" />
            <p className="text-sm font-semibold text-foreground">No reports match criteria</p>
            <p className="text-xs text-muted-foreground font-mono">
              Adjust filters to view other reports or clear your selection.
            </p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead>
                <tr className="border-b border-border bg-secondary/20">
                  <th className="w-10 px-3 py-3 text-center">
                    <input
                      type="checkbox"
                      checked={isAllSelected}
                      onChange={(e) => handleSelectAll(e.target.checked)}
                      aria-label="Select all reports"
                      className="rounded border-border accent-primary h-3.5 w-3.5 cursor-pointer"
                    />
                  </th>
                  <th className="text-left px-4 py-3 font-mono uppercase tracking-wider text-muted-foreground font-semibold text-[10px] whitespace-nowrap">
                    Centre Office
                  </th>
                  <th className="text-left px-4 py-3 font-mono uppercase tracking-wider text-muted-foreground font-semibold text-[10px] whitespace-nowrap">
                    State
                  </th>
                  <th className="text-left px-4 py-3 font-mono uppercase tracking-wider text-muted-foreground font-semibold text-[10px] whitespace-nowrap">
                    Wait Time
                  </th>
                  <th className="text-left px-4 py-3 font-mono uppercase tracking-wider text-muted-foreground font-semibold text-[10px] whitespace-nowrap">
                    Status
                  </th>
                  <th className="text-left px-4 py-3 font-mono uppercase tracking-wider text-muted-foreground font-semibold text-[10px] whitespace-nowrap">
                    Reported By
                  </th>
                  <th className="text-left px-4 py-3 font-mono uppercase tracking-wider text-muted-foreground font-semibold text-[10px] whitespace-nowrap">
                    Timestamp
                  </th>
                  <th className="text-right px-4 py-3 font-mono uppercase tracking-wider text-muted-foreground font-semibold text-[10px] whitespace-nowrap">
                    Actions
                  </th>
                </tr>
              </thead>
              <tbody className="divide-y divide-border/60">
                {filteredReports.map((r) => {
                  const badge = waitBadge(r.wait_minutes);
                  const isChecked = selectedIds.includes(r.id);

                  return (
                    <tr
                      key={r.id}
                      className={`hover:bg-secondary/40 transition-colors ${
                        isChecked ? "bg-secondary/30" : ""
                      }`}
                    >
                      <td className="w-10 px-3 py-3 text-center">
                        <input
                          type="checkbox"
                          checked={isChecked}
                          onChange={(e) => handleSelectRow(r.id, e.target.checked)}
                          aria-label={`Select report for ${r.center_name}`}
                          className="rounded border-border accent-primary h-3.5 w-3.5 cursor-pointer"
                        />
                      </td>

                      <td className="px-4 py-3 font-medium text-foreground max-w-[200px] truncate">
                        {r.center_name}
                      </td>

                      <td className="px-4 py-3 text-muted-foreground whitespace-nowrap">
                        {r.state}
                      </td>

                      <td className="px-4 py-3 font-mono font-semibold text-foreground whitespace-nowrap">
                        {formatMinutes(r.wait_minutes)}
                      </td>

                      <td className="px-4 py-3 whitespace-nowrap">
                        <Badge
                          variant="outline"
                          className={`text-[10px] font-mono ${badge.cls}`}
                        >
                          {badge.label}
                        </Badge>
                      </td>

                      <td className="px-4 py-3 max-w-[180px] truncate">
                        <span className="font-medium text-foreground block truncate">
                          {r.reporter_name}
                        </span>
                        <span className="text-[10px] font-mono text-muted-foreground">
                          {r.masked_phone}
                        </span>
                      </td>

                      <td className="px-4 py-3 font-mono text-muted-foreground whitespace-nowrap">
                        {new Date(r.reported_at).toLocaleString("en-GB", {
                          day: "numeric",
                          month: "short",
                          year: "numeric",
                          hour: "2-digit",
                          minute: "2-digit",
                        })}
                      </td>

                      <td className="px-4 py-3 text-right whitespace-nowrap">
                        <DeleteReportButton reportId={r.id} centreName={r.center_name} />
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </Card>

      {/* Bulk Delete Confirm Dialog */}
      <Dialog open={bulkDialogOpen} onOpenChange={setBulkDialogOpen}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle className="text-base text-destructive flex items-center gap-2">
              <AlertTriangle className="h-4 w-4" />
              Delete {selectedIds.length} Reports?
            </DialogTitle>
            <DialogDescription className="text-xs text-muted-foreground pt-1">
              Are you sure you want to delete these {selectedIds.length} selected wait-time reports?
              They will be permanently removed from citizen tracker metrics and logged to the audit ledger.
            </DialogDescription>
          </DialogHeader>

          <DialogFooter className="gap-2 sm:gap-0 mt-4">
            <DialogClose asChild>
              <Button variant="outline" size="sm" disabled={isBulkPending}>
                Cancel
              </Button>
            </DialogClose>
            <Button
              variant="destructive"
              size="sm"
              disabled={isBulkPending}
              onClick={handleBulkDelete}
              className="gap-1.5"
            >
              {isBulkPending ? (
                <>
                  <Loader2 className="h-3.5 w-3.5 animate-spin" />
                  Deleting...
                </>
              ) : (
                `Confirm Delete (${selectedIds.length})`
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use client";

import { useState, useTransition } from "react";
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  ShieldCheck,
  ShieldAlert,
  Calendar,
  Phone,
  Trash2,
  UserCog,
  Loader2,
  BookOpen,
  GraduationCap,
  Fingerprint,
  Building2,
  CheckCircle2,
  Circle,
} from "lucide-react";
import { toast } from "sonner";
import { deleteUserAction, changeUserRoleAction } from "./actions";
import { getLevelName } from "@/types";

export interface UserDetail {
  id: string;
  full_name: string;
  avatar_url: string | null;
  phone_number: string | null;
  masked_phone: string;
  email?: string;
  level_id: number;
  is_verified: boolean;
  role: string;
  created_at: string;
  updated_at?: string;
  guidesProgress?: Record<
    string,
    {
      started: boolean;
      completed: boolean;
      completed_steps?: string[];
      steps?: string[];
      current_step_id?: string;
    }
  >;
}

interface UserDetailDrawerProps {
  user: UserDetail | null;
  currentAdminId: string;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onUserUpdated?: () => void;
}

const guideIcons: Record<string, React.ElementType> = {
  passport: BookOpen,
  nysc: GraduationCap,
  "nin-bvn": Fingerprint,
  cac: Building2,
};

const guideNames: Record<string, string> = {
  passport: "Nigerian Passport",
  nysc: "NYSC Mobilisation",
  "nin-bvn": "NIN & BVN Registration",
  cac: "CAC Business Registration",
};

export function UserDetailDrawer({
  user,
  currentAdminId,
  open,
  onOpenChange,
  onUserUpdated,
}: UserDetailDrawerProps) {
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [roleDialogOpen, setRoleDialogOpen] = useState(false);
  const [typedEmail, setTypedEmail] = useState("");
  const [selectedRole, setSelectedRole] = useState<"user" | "admin">("user");
  const [isPending, startTransition] = useTransition();

  if (!user) return null;

  const isSelf = user.id === currentAdminId;
  const isTargetAdmin = user.role === "admin";
  const expectedEmail = user.email || "";

  const getInitials = (name?: string | null) => {
    if (!name) return "ZE";
    const parts = name.trim().split(" ");
    if (parts.length >= 2) return `${parts[0][0]}${parts[1][0]}`.toUpperCase();
    return parts[0].slice(0, 2).toUpperCase();
  };

  const handleDelete = () => {
    startTransition(async () => {
      const res = await deleteUserAction(user.id, typedEmail);
      if (!res.success) {
        toast.error(res.error || "Failed to delete user.");
      } else {
        toast.success(`User ${user.full_name} has been permanently deleted.`);
        setDeleteDialogOpen(false);
        onOpenChange(false);
        onUserUpdated?.();
      }
    });
  };

  const handleRoleChange = () => {
    startTransition(async () => {
      const res = await changeUserRoleAction(user.id, selectedRole);
      if (!res.success) {
        toast.error(res.error || "Failed to change role.");
      } else {
        toast.success(`Role updated to ${selectedRole} for ${user.full_name}.`);
        setRoleDialogOpen(false);
        onOpenChange(false);
        onUserUpdated?.();
      }
    });
  };

  return (
    <>
      <Sheet open={open} onOpenChange={onOpenChange}>
        <SheetContent className="w-full sm:max-w-md p-0 flex flex-col bg-card border-border overflow-y-auto">
          {/* Header */}
          <SheetHeader className="p-5 border-b border-border/70 text-left space-y-4">
            <div className="flex items-center gap-3">
              <Avatar className="h-12 w-12 border border-border shrink-0">
                <AvatarImage src={user.avatar_url || ""} />
                <AvatarFallback className="font-mono text-sm font-bold">
                  {getInitials(user.full_name)}
                </AvatarFallback>
              </Avatar>
              <div className="min-w-0 flex-1">
                <SheetTitle className="text-base font-bold text-foreground truncate">
                  {user.full_name || "Citizen"}
                </SheetTitle>
                <SheetDescription className="text-xs font-mono text-muted-foreground truncate">
                  {user.email || user.masked_phone}
                </SheetDescription>
                <div className="flex items-center gap-1.5 mt-1.5 flex-wrap">
                  <Badge
                    variant="outline"
                    className={
                      user.role === "admin"
                        ? "border-amber-500/30 bg-amber-500/10 text-amber-500 text-[10px] font-mono uppercase"
                        : "border-border text-muted-foreground text-[10px] font-mono"
                    }
                  >
                    {user.role}
                  </Badge>
                  <Badge
                    variant="outline"
                    className={`text-[10px] font-mono gap-1 ${
                      user.is_verified
                        ? "border-emerald-500/30 bg-emerald-500/10 text-emerald-500"
                        : "border-amber-500/30 bg-amber-500/10 text-amber-500"
                    }`}
                  >
                    {user.is_verified ? (
                      <>
                        <ShieldCheck className="h-3 w-3" />
                        Verified
                      </>
                    ) : (
                      <>
                        <ShieldAlert className="h-3 w-3" />
                        Unverified
                      </>
                    )}
                  </Badge>
                  <Badge
                    variant="outline"
                    className="border-primary/30 bg-primary/10 text-primary text-[10px] font-mono"
                  >
                    Level {user.level_id} · {getLevelName(user.level_id)}
                  </Badge>
                </div>
              </div>
            </div>
          </SheetHeader>

          {/* Profile Details & Metadata */}
          <div className="p-5 space-y-6 flex-1">
            {/* Metadata Grid */}
            <div className="space-y-2">
              <h4 className="text-[11px] font-mono uppercase tracking-wider text-muted-foreground font-semibold">
                Account Information
              </h4>
              <div className="rounded-lg border border-border bg-secondary/20 p-3 space-y-2 text-xs">
                <div className="flex items-center justify-between">
                  <span className="text-muted-foreground flex items-center gap-1.5">
                    <Phone className="h-3.5 w-3.5" />
                    Phone (Masked)
                  </span>
                  <span className="font-mono text-foreground">{user.masked_phone}</span>
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-muted-foreground flex items-center gap-1.5">
                    <Calendar className="h-3.5 w-3.5" />
                    Joined Date
                  </span>
                  <span className="font-mono text-foreground">
                    {new Date(user.created_at).toLocaleString("en-GB", {
                      day: "numeric",
                      month: "short",
                      year: "numeric",
                      hour: "2-digit",
                      minute: "2-digit",
                    })}
                  </span>
                </div>
                {user.updated_at && (
                  <div className="flex items-center justify-between">
                    <span className="text-muted-foreground">Last Updated</span>
                    <span className="font-mono text-foreground">
                      {new Date(user.updated_at).toLocaleDateString("en-GB", {
                        day: "numeric",
                        month: "short",
                        year: "numeric",
                      })}
                    </span>
                  </div>
                )}
                <div className="flex items-center justify-between border-t border-border/50 pt-2 text-[11px]">
                  <span className="text-muted-foreground">Identity Privacy</span>
                  <span className="font-mono text-emerald-500">
                    Salted SHA-256 (Raw NIN never stored)
                  </span>
                </div>
              </div>
            </div>

            {/* Guide Progress */}
            <div className="space-y-2.5">
              <h4 className="text-[11px] font-mono uppercase tracking-wider text-muted-foreground font-semibold">
                Guide Progress (nav_progress)
              </h4>
              <div className="space-y-2">
                {["passport", "nysc", "nin-bvn", "cac"].map((fid) => {
                  const Icon = guideIcons[fid] || BookOpen;
                  const name = guideNames[fid] || fid;
                  const prog = user.guidesProgress?.[fid];
                  const completedCount = prog?.completed_steps?.length || 0;
                  const totalSteps = prog?.steps?.length || 0;
                  const isDone =
                    prog?.completed || (totalSteps > 0 && completedCount === totalSteps);

                  return (
                    <div
                      key={fid}
                      className="rounded-lg border border-border bg-card p-3 flex items-center justify-between gap-3 text-xs"
                    >
                      <div className="flex items-center gap-2.5 min-w-0">
                        <div className="p-1.5 rounded-md border border-border bg-secondary/50 text-muted-foreground">
                          <Icon className="h-3.5 w-3.5" />
                        </div>
                        <div className="min-w-0">
                          <p className="font-medium text-foreground truncate">{name}</p>
                          <p className="text-[10px] font-mono text-muted-foreground">
                            {prog?.started
                              ? `${completedCount} of ${totalSteps || "?"} steps completed`
                              : "Not started"}
                          </p>
                        </div>
                      </div>

                      {isDone ? (
                        <Badge
                          variant="outline"
                          className="border-emerald-500/30 bg-emerald-500/10 text-emerald-500 text-[10px] font-mono gap-1 shrink-0"
                        >
                          <CheckCircle2 className="h-3 w-3" />
                          Complete
                        </Badge>
                      ) : prog?.started ? (
                        <Badge
                          variant="outline"
                          className="border-blue-500/30 bg-blue-500/10 text-blue-400 text-[10px] font-mono shrink-0"
                        >
                          In Progress
                        </Badge>
                      ) : (
                        <Badge
                          variant="outline"
                          className="border-border text-muted-foreground text-[10px] font-mono shrink-0"
                        >
                          Idle
                        </Badge>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Actions with Safeguards */}
            <div className="space-y-2.5 pt-2 border-t border-border/70">
              <h4 className="text-[11px] font-mono uppercase tracking-wider text-muted-foreground font-semibold">
                Administrative Actions
              </h4>

              <div className="grid grid-cols-2 gap-2">
                {/* Change Role Button */}
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => {
                    setSelectedRole(user.role === "admin" ? "user" : "admin");
                    setRoleDialogOpen(true);
                  }}
                  disabled={isSelf}
                  className="gap-1.5 text-xs border-border hover:bg-secondary"
                >
                  <UserCog className="h-3.5 w-3.5" />
                  <span>{user.role === "admin" ? "Demote to User" : "Make Admin"}</span>
                </Button>

                {/* Delete User Button */}
                <Button
                  variant="destructive"
                  size="sm"
                  onClick={() => {
                    setTypedEmail("");
                    setDeleteDialogOpen(true);
                  }}
                  disabled={isSelf || isTargetAdmin}
                  className="gap-1.5 text-xs"
                >
                  <Trash2 className="h-3.5 w-3.5" />
                  <span>Delete User</span>
                </Button>
              </div>

              {isSelf && (
                <p className="text-[10px] text-muted-foreground font-mono">
                  * You cannot modify or delete your own admin account.
                </p>
              )}
              {!isSelf && isTargetAdmin && (
                <p className="text-[10px] text-muted-foreground font-mono">
                  * Other administrators cannot be directly deleted. Demote first if necessary.
                </p>
              )}
            </div>
          </div>
        </SheetContent>
      </Sheet>

      {/* Delete User Safeguard Dialog */}
      <Dialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle className="text-base text-destructive flex items-center gap-2">
              <Trash2 className="h-4 w-4" />
              Permanently Delete User?
            </DialogTitle>
            <DialogDescription className="text-xs text-muted-foreground pt-1 space-y-2">
              <p>
                This action is irreversible. It will delete the user account from Supabase Auth and cascade
                to all citizen profiles, documents, and guide progress.
              </p>
              <div className="p-2.5 rounded-md border border-border bg-secondary/50 font-mono text-[11px] text-foreground">
                To confirm, type the user&apos;s email address:
                <strong className="block mt-0.5 text-foreground">{expectedEmail || "(no email on file)"}</strong>
              </div>
            </DialogDescription>
          </DialogHeader>

          <div className="py-2">
            <input
              type="email"
              value={typedEmail}
              onChange={(e) => setTypedEmail(e.target.value)}
              placeholder="Type user's email to confirm..."
              className="w-full h-9 px-3 rounded-lg border border-border bg-secondary/40 text-xs font-mono text-foreground placeholder:text-muted-foreground outline-none focus:border-destructive transition-colors"
            />
          </div>

          <DialogFooter className="gap-2 sm:gap-0">
            <DialogClose asChild>
              <Button variant="outline" size="sm" disabled={isPending}>
                Cancel
              </Button>
            </DialogClose>
            <Button
              variant="destructive"
              size="sm"
              disabled={
                isPending ||
                !expectedEmail ||
                typedEmail.trim().toLowerCase() !== expectedEmail.trim().toLowerCase()
              }
              onClick={handleDelete}
              className="gap-1.5"
            >
              {isPending ? (
                <>
                  <Loader2 className="h-3.5 w-3.5 animate-spin" />
                  Deleting...
                </>
              ) : (
                "Delete Account"
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Change Role Safeguard Dialog */}
      <Dialog open={roleDialogOpen} onOpenChange={setRoleDialogOpen}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle className="text-base flex items-center gap-2">
              <UserCog className="h-4 w-4 text-primary" />
              Change User Role
            </DialogTitle>
            <DialogDescription className="text-xs text-muted-foreground pt-1">
              Change permissions for{" "}
              <strong className="text-foreground">{user.full_name}</strong>.
              Administrators have full read access to all citizen data, moderation tools, and the audit ledger.
            </DialogDescription>
          </DialogHeader>

          <div className="py-3 space-y-2">
            <label className="text-xs font-semibold text-foreground">Select New Role:</label>
            <div className="grid grid-cols-2 gap-2">
              <button
                type="button"
                onClick={() => setSelectedRole("user")}
                className={`p-3 rounded-lg border text-left text-xs transition-colors ${
                  selectedRole === "user"
                    ? "border-primary bg-primary/10 text-foreground font-semibold"
                    : "border-border text-muted-foreground hover:bg-secondary/40"
                }`}
              >
                <span className="block font-medium">Citizen (User)</span>
                <span className="text-[10px] text-muted-foreground">Standard access</span>
              </button>
              <button
                type="button"
                onClick={() => setSelectedRole("admin")}
                className={`p-3 rounded-lg border text-left text-xs transition-colors ${
                  selectedRole === "admin"
                    ? "border-amber-500 bg-amber-500/10 text-foreground font-semibold"
                    : "border-border text-muted-foreground hover:bg-secondary/40"
                }`}
              >
                <span className="block font-medium text-amber-500">Administrator</span>
                <span className="text-[10px] text-muted-foreground">Full console access</span>
              </button>
            </div>
          </div>

          <DialogFooter className="gap-2 sm:gap-0">
            <DialogClose asChild>
              <Button variant="outline" size="sm" disabled={isPending}>
                Cancel
              </Button>
            </DialogClose>
            <Button
              variant="default"
              size="sm"
              disabled={isPending || selectedRole === user.role}
              onClick={handleRoleChange}
              className="gap-1.5"
            >
              {isPending ? (
                <>
                  <Loader2 className="h-3.5 w-3.5 animate-spin" />
                  Saving...
                </>
              ) : (
                "Update Role"
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

"use client";

import { useState, useMemo, useTransition } from "react";
import { useRouter } from "next/navigation";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import {
  Search,
  Download,
  Filter,
  ArrowUpDown,
  ArrowUp,
  ArrowDown,
  ShieldCheck,
  ShieldAlert,
  Loader2,
  Users,
} from "lucide-react";
import { toast } from "sonner";
import { UserDetail, UserDetailDrawer } from "./UserDetailDrawer";
import { exportUsersCsvAction } from "./actions";
import { getLevelName } from "@/types";

interface UsersTableClientProps {
  users: UserDetail[];
  currentAdminId: string;
}

type SortField = "name" | "level" | "verified" | "joined";
type SortDirection = "asc" | "desc";

export function UsersTableClient({ users, currentAdminId }: UsersTableClientProps) {
  const router = useRouter();
  const [search, setSearch] = useState("");
  const [filterVerified, setFilterVerified] = useState<string>("all");
  const [filterRole, setFilterRole] = useState<string>("all");
  const [filterLevel, setFilterLevel] = useState<string>("all");
  const [sortField, setSortField] = useState<SortField>("joined");
  const [sortDirection, setSortDirection] = useState<SortDirection>("desc");

  const [selectedUser, setSelectedUser] = useState<UserDetail | null>(null);
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [isExporting, startExportTransition] = useTransition();

  // Filtered and sorted data
  const filteredUsers = useMemo(() => {
    return users.filter((u) => {
      // Search by name
      if (search.trim()) {
        const query = search.toLowerCase().trim();
        const matchesName = (u.full_name || "").toLowerCase().includes(query);
        const matchesEmail = (u.email || "").toLowerCase().includes(query);
        if (!matchesName && !matchesEmail) return false;
      }

      // Filter by verification
      if (filterVerified === "verified" && !u.is_verified) return false;
      if (filterVerified === "unverified" && u.is_verified) return false;

      // Filter by role
      if (filterRole !== "all" && u.role !== filterRole) return false;

      // Filter by level
      if (filterLevel !== "all" && u.level_id !== parseInt(filterLevel, 10)) return false;

      return true;
    });
  }, [users, search, filterVerified, filterRole, filterLevel]);

  const sortedUsers = useMemo(() => {
    return [...filteredUsers].sort((a, b) => {
      let comparison = 0;
      if (sortField === "name") {
        comparison = (a.full_name || "").localeCompare(b.full_name || "");
      } else if (sortField === "level") {
        comparison = a.level_id - b.level_id;
      } else if (sortField === "verified") {
        comparison = (a.is_verified ? 1 : 0) - (b.is_verified ? 1 : 0);
      } else if (sortField === "joined") {
        comparison = new Date(a.created_at).getTime() - new Date(b.created_at).getTime();
      }

      return sortDirection === "asc" ? comparison : -comparison;
    });
  }, [filteredUsers, sortField, sortDirection]);

  const toggleSort = (field: SortField) => {
    if (sortField === field) {
      setSortDirection((prev) => (prev === "asc" ? "desc" : "asc"));
    } else {
      setSortField(field);
      setSortDirection("asc");
    }
  };

  const handleRowClick = (user: UserDetail) => {
    setSelectedUser(user);
    setDrawerOpen(true);
  };

  const handleExportCsv = () => {
    startExportTransition(async () => {
      const res = await exportUsersCsvAction();
      if (!res.success || !res.csv) {
        toast.error(res.error || "Failed to export CSV.");
      } else {
        const blob = new Blob([res.csv], { type: "text/csv;charset=utf-8;" });
        const url = URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url;
        a.download = `zed_citizens_${new Date().toISOString().slice(0, 10)}.csv`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
        toast.success("Users CSV exported successfully.");
      }
    });
  };

  const getInitials = (name?: string | null) => {
    if (!name) return "ZE";
    const parts = name.trim().split(" ");
    if (parts.length >= 2) return `${parts[0][0]}${parts[1][0]}`.toUpperCase();
    return parts[0].slice(0, 2).toUpperCase();
  };

  const renderSortIndicator = (field: SortField) => {
    if (sortField !== field) {
      return <ArrowUpDown className="h-3 w-3 text-muted-foreground/50" />;
    }
    return sortDirection === "asc" ? (
      <ArrowUp className="h-3 w-3 text-primary" />
    ) : (
      <ArrowDown className="h-3 w-3 text-primary" />
    );
  };

  return (
    <div className="space-y-4">
      {/* Control Bar: Search, Filters, CSV Export */}
      <Card className="p-3.5 border-border bg-card shadow-xs">
        <div className="flex flex-col md:flex-row items-stretch md:items-center justify-between gap-3">
          {/* Search Input */}
          <div className="relative flex-1 max-w-sm">
            <Search className="absolute left-2.5 top-2.5 h-3.5 w-3.5 text-muted-foreground" />
            <input
              type="text"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search citizens by name..."
              className="w-full h-8 pl-8 pr-3 rounded-md border border-border bg-secondary/40 text-xs text-foreground placeholder:text-muted-foreground outline-none focus:border-primary transition-colors"
            />
          </div>

          {/* Filters & Export */}
          <div className="flex flex-wrap items-center gap-2">
            {/* Filter: Verified */}
            <select
              value={filterVerified}
              onChange={(e) => setFilterVerified(e.target.value)}
              className="h-8 px-2.5 rounded-md border border-border bg-secondary/40 text-xs text-foreground outline-none focus:border-primary transition-colors"
            >
              <option value="all">All Status</option>
              <option value="verified">Verified Only</option>
              <option value="unverified">Unverified Only</option>
            </select>

            {/* Filter: Role */}
            <select
              value={filterRole}
              onChange={(e) => setFilterRole(e.target.value)}
              className="h-8 px-2.5 rounded-md border border-border bg-secondary/40 text-xs text-foreground outline-none focus:border-primary transition-colors"
            >
              <option value="all">All Roles</option>
              <option value="user">User (Citizen)</option>
              <option value="admin">Administrator</option>
            </select>

            {/* Filter: Level */}
            <select
              value={filterLevel}
              onChange={(e) => setFilterLevel(e.target.value)}
              className="h-8 px-2.5 rounded-md border border-border bg-secondary/40 text-xs text-foreground outline-none focus:border-primary transition-colors"
            >
              <option value="all">All Levels</option>
              <option value="1">Level 1 · Rookie</option>
              <option value="2">Level 2 · Explorer</option>
              <option value="3">Level 3 · Builder</option>
              <option value="4">Level 4 · Pro</option>
              <option value="5">Level 5 · Zed Legend</option>
            </select>

            {/* Export CSV Button */}
            <Button
              variant="outline"
              size="sm"
              onClick={handleExportCsv}
              disabled={isExporting}
              className="h-8 text-xs border-border gap-1.5"
            >
              {isExporting ? (
                <Loader2 className="h-3 w-3 animate-spin" />
              ) : (
                <Download className="h-3 w-3" />
              )}
              <span>Export CSV</span>
            </Button>
          </div>
        </div>
      </Card>

      {/* Results Count & Hint */}
      <div className="flex items-center justify-between text-xs text-muted-foreground font-mono px-1">
        <span>
          Showing {sortedUsers.length} of {users.length} citizens
          {(search || filterVerified !== "all" || filterRole !== "all" || filterLevel !== "all") &&
            " (filtered)"}
        </span>
        <span className="text-[11px] hidden sm:inline text-muted-foreground/80">
          * Click on any row to open full profile & guide progress
        </span>
      </div>

      {/* Main Table */}
      <Card className="border-border bg-card shadow-xs overflow-hidden">
        {sortedUsers.length === 0 ? (
          <div className="p-12 text-center space-y-2">
            <Users className="h-8 w-8 text-muted-foreground mx-auto opacity-40" />
            <p className="text-sm font-semibold text-foreground">No citizens found</p>
            <p className="text-xs text-muted-foreground font-mono">
              Try adjusting your search or filter settings.
            </p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead>
                <tr className="border-b border-border bg-secondary/20">
                  {/* Name Sortable */}
                  <th
                    onClick={() => toggleSort("name")}
                    className="text-left px-4 py-3 font-mono uppercase tracking-wider text-muted-foreground font-semibold text-[10px] whitespace-nowrap cursor-pointer hover:text-foreground select-none"
                  >
                    <div className="flex items-center gap-1.5">
                      <span>Citizen Name</span>
                      {renderSortIndicator("name")}
                    </div>
                  </th>

                  <th className="text-left px-4 py-3 font-mono uppercase tracking-wider text-muted-foreground font-semibold text-[10px] whitespace-nowrap">
                    Phone (Masked)
                  </th>

                  {/* Level Sortable */}
                  <th
                    onClick={() => toggleSort("level")}
                    className="text-left px-4 py-3 font-mono uppercase tracking-wider text-muted-foreground font-semibold text-[10px] whitespace-nowrap cursor-pointer hover:text-foreground select-none"
                  >
                    <div className="flex items-center gap-1.5">
                      <span>Level</span>
                      {renderSortIndicator("level")}
                    </div>
                  </th>

                  {/* Verified Sortable */}
                  <th
                    onClick={() => toggleSort("verified")}
                    className="text-left px-4 py-3 font-mono uppercase tracking-wider text-muted-foreground font-semibold text-[10px] whitespace-nowrap cursor-pointer hover:text-foreground select-none"
                  >
                    <div className="flex items-center gap-1.5">
                      <span>Status</span>
                      {renderSortIndicator("verified")}
                    </div>
                  </th>

                  <th className="text-left px-4 py-3 font-mono uppercase tracking-wider text-muted-foreground font-semibold text-[10px] whitespace-nowrap">
                    Role
                  </th>

                  {/* Joined Date Sortable */}
                  <th
                    onClick={() => toggleSort("joined")}
                    className="text-right px-4 py-3 font-mono uppercase tracking-wider text-muted-foreground font-semibold text-[10px] whitespace-nowrap cursor-pointer hover:text-foreground select-none"
                  >
                    <div className="flex items-center justify-end gap-1.5">
                      <span>Joined Date</span>
                      {renderSortIndicator("joined")}
                    </div>
                  </th>
                </tr>
              </thead>
              <tbody className="divide-y divide-border/60">
                {sortedUsers.map((u) => (
                  <tr
                    key={u.id}
                    onClick={() => handleRowClick(u)}
                    className="hover:bg-secondary/40 transition-colors cursor-pointer group"
                  >
                    <td className="px-4 py-3">
                      <div className="flex items-center gap-2.5">
                        <Avatar className="h-7 w-7 border border-border shrink-0">
                          <AvatarImage src={u.avatar_url || ""} />
                          <AvatarFallback className="font-mono text-[10px] font-bold">
                            {getInitials(u.full_name)}
                          </AvatarFallback>
                        </Avatar>
                        <div className="min-w-0 max-w-[200px]">
                          <span className="font-semibold text-foreground block truncate group-hover:text-primary transition-colors">
                            {u.full_name || "Citizen"}
                          </span>
                          {u.email && (
                            <span className="text-[10px] font-mono text-muted-foreground block truncate">
                              {u.email}
                            </span>
                          )}
                        </div>
                      </div>
                    </td>

                    <td className="px-4 py-3 font-mono text-muted-foreground whitespace-nowrap">
                      {u.masked_phone}
                    </td>

                    <td className="px-4 py-3 whitespace-nowrap">
                      <span className="font-mono font-medium text-foreground">
                        {getLevelName(u.level_id)}
                      </span>
                    </td>

                    <td className="px-4 py-3 whitespace-nowrap">
                      {u.is_verified ? (
                        <Badge
                          variant="outline"
                          className="border-emerald-500/30 bg-emerald-500/10 text-emerald-500 text-[10px] font-mono gap-1"
                        >
                          <ShieldCheck className="h-3 w-3" />
                          Verified
                        </Badge>
                      ) : (
                        <Badge
                          variant="outline"
                          className="border-amber-500/30 bg-amber-500/10 text-amber-500 text-[10px] font-mono gap-1"
                        >
                          <ShieldAlert className="h-3 w-3" />
                          Unverified
                        </Badge>
                      )}
                    </td>

                    <td className="px-4 py-3 whitespace-nowrap">
                      <Badge
                        variant="outline"
                        className={
                          u.role === "admin"
                            ? "border-amber-500/30 bg-amber-500/10 text-amber-500 text-[10px] font-mono uppercase font-semibold"
                            : "border-border text-muted-foreground text-[10px] font-mono uppercase"
                        }
                      >
                        {u.role}
                      </Badge>
                    </td>

                    <td className="px-4 py-3 font-mono text-muted-foreground text-right whitespace-nowrap">
                      {new Date(u.created_at).toLocaleDateString("en-GB", {
                        day: "numeric",
                        month: "short",
                        year: "numeric",
                      })}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </Card>

      {/* User Detail Drawer Sheet */}
      <UserDetailDrawer
        user={selectedUser}
        currentAdminId={currentAdminId}
        open={drawerOpen}
        onOpenChange={setDrawerOpen}
        onUserUpdated={() => router.refresh()}
      />
    </div>
  );
}

"use client";

import Link from "next/link";
import Image from "next/image";
import { usePathname } from "next/navigation";
import { cn } from "@/lib/utils";
import {
  LayoutDashboard,
  Users,
  FileText,
  ScrollText,
  ArrowLeft,
  ShieldAlert,
} from "lucide-react";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";

interface AdminSidebarProps {
  adminUser: {
    id: string;
    fullName: string;
    email?: string;
    avatarUrl?: string;
  };
}

const navItems = [
  { href: "/admin", label: "Overview", icon: LayoutDashboard, exact: true },
  { href: "/admin/users", label: "Users", icon: Users, exact: false },
  { href: "/admin/reports", label: "Reports", icon: FileText, exact: false },
  { href: "/admin/audit-log", label: "Audit Log", icon: ScrollText, exact: false },
];

export function AdminSidebar({ adminUser }: AdminSidebarProps) {
  const pathname = usePathname();

  const getInitials = (name?: string | null) => {
    if (!name) return "AD";
    const parts = name.trim().split(" ");
    if (parts.length >= 2) return `${parts[0][0]}${parts[1][0]}`.toUpperCase();
    return parts[0].slice(0, 2).toUpperCase();
  };

  return (
    <aside
      aria-label="Admin console navigation"
      className="hidden md:flex flex-col w-[230px] shrink-0 border-r border-border bg-card/60 backdrop-blur-md sticky top-0 h-dvh select-none z-30"
    >
      {/* Brand Header */}
      <div className="flex h-13 items-center justify-between border-b border-border px-4">
        <Link href="/admin" className="flex items-center gap-2" aria-label="Zed Admin Console">
          <Image
            src="/icons/zed-logo-full-light.png"
            alt="The Zed Project"
            width={100}
            height={50}
            className="h-6 w-auto object-contain dark:hidden"
          />
          <Image
            src="/icons/zed-logo-full-dark.png"
            alt="The Zed Project"
            width={100}
            height={50}
            className="h-6 w-auto object-contain hidden dark:block"
          />
          <span className="rounded bg-amber-500/15 border border-amber-500/30 px-1.5 py-0.5 font-mono text-[9px] font-bold text-amber-500 tracking-wider">
            CONSOLE
          </span>
        </Link>

        <span className="h-2 w-2 rounded-full bg-emerald-500 animate-pulse" title="System operational" />
      </div>

      {/* Nav List */}
      <nav className="flex-1 overflow-y-auto px-2.5 py-4 space-y-5">
        <div className="space-y-1">
          <p className="px-2 pb-1.5 font-mono text-[9px] font-semibold tracking-wider uppercase text-muted-foreground">
            MANAGEMENT
          </p>

          <ul className="space-y-0.5" role="list">
            {navItems.map(({ href, label, icon: Icon, exact }) => {
              const isActive = exact
                ? pathname === href
                : pathname === href || pathname.startsWith(href + "/");

              return (
                <li key={href}>
                  <Link
                    href={href}
                    aria-current={isActive ? "page" : undefined}
                    className={cn(
                      "flex items-center gap-2.5 rounded-md px-2.5 py-2 text-xs font-medium transition-colors group",
                      isActive
                        ? "bg-secondary text-foreground font-semibold shadow-xs border border-border"
                        : "text-muted-foreground hover:bg-secondary/60 hover:text-foreground border border-transparent"
                    )}
                  >
                    <Icon
                      className={cn(
                        "h-3.5 w-3.5 shrink-0 transition-colors",
                        isActive
                          ? "text-primary"
                          : "text-muted-foreground group-hover:text-foreground"
                      )}
                    />
                    <span className="truncate">{label}</span>
                  </Link>
                </li>
              );
            })}
          </ul>
        </div>

        {/* Quick Shortcut back to platform */}
        <div className="space-y-1 pt-2">
          <p className="px-2 pb-1.5 font-mono text-[9px] font-semibold tracking-wider uppercase text-muted-foreground">
            NAVIGATION
          </p>
          <Link
            href="/home"
            className="flex items-center gap-2.5 rounded-md px-2.5 py-2 text-xs font-medium text-muted-foreground hover:bg-secondary/60 hover:text-foreground border border-transparent transition-colors"
          >
            <ArrowLeft className="h-3.5 w-3.5" />
            <span>Back to citizen app</span>
          </Link>
        </div>
      </nav>

      {/* Admin User Footer */}
      <div className="border-t border-border p-3">
        <div className="flex items-center gap-2.5 rounded-lg border border-border bg-secondary/30 p-2">
          <Avatar className="h-7 w-7 border border-border shrink-0">
            <AvatarImage src={adminUser.avatarUrl || ""} />
            <AvatarFallback className="bg-secondary font-mono text-[10px] font-bold text-foreground">
              {getInitials(adminUser.fullName)}
            </AvatarFallback>
          </Avatar>
          <div className="flex flex-1 flex-col overflow-hidden text-left">
            <span className="truncate text-xs font-semibold text-foreground">
              {adminUser.fullName}
            </span>
            <div className="flex items-center gap-1.5">
              <span className="h-1.5 w-1.5 rounded-full bg-amber-500 shrink-0" />
              <span className="font-mono text-[9px] text-amber-500 uppercase font-semibold">
                Super Admin
              </span>
            </div>
          </div>
        </div>
      </div>
    </aside>
  );
}

